import{_ as t,o as a,c as s,a3 as l}from"./chunks/framework.CgYN3nbS.js";const b=JSON.parse('{"title":"Lab 05 — Écrire pour Mélanie","description":"","frontmatter":{"title":"Lab 05 — Écrire pour Mélanie","aside":false},"headers":[],"relativePath":"labs/lab05-ecrire-pour-melanie.md","filePath":"labs/lab05-ecrire-pour-melanie.md"}'),r={name:"labs/lab05-ecrire-pour-melanie.md"};function i(n,e,o,u,c,p){return a(),s("div",null,[...e[0]||(e[0]=[l('<h1 id="lab-05-—-ecrire-pour-melanie" tabindex="-1">Lab 05 — Écrire pour Mélanie <a class="header-anchor" href="#lab-05-—-ecrire-pour-melanie" aria-label="Permalink to &quot;Lab 05 — Écrire pour Mélanie&quot;">​</a></h1><div class="bg-blue-50 border border-blue-200 text-blue-900 rounded-lg p-4 mb-5"><strong>Objectifs du laboratoire</strong><br><ul class="list-disc pl-5"><li>Mettre au propre la section 6 de votre question : une phrase d&#39;ouverture, le tableau de comparaison, les avantages et les limites pour l&#39;entreprise.</li><li>Écrire la mise en contexte et la portée du rapport.</li><li>Relire le texte d&#39;un autre membre de l&#39;équipe comme le ferait Mélanie.</li><li>Écrire une première version du résumé.</li></ul></div><div class="bg-yellow-50 border border-yellow-200 text-yellow-900 rounded-lg p-4 mb-5"><strong>Modalités</strong><br><ul class="list-disc pl-5"><li>Avec <strong>votre équipe de la session</strong>, directement dans le <strong>rapport de l&#39;évaluation 1</strong> (le gabarit Word, dans le dossier partagé de l&#39;équipe). Pas de fiche ce soir : ce que vous écrivez est déjà le rapport.</li><li>Durée : de 20 h 30 à la fin de la soirée, en équipe, après la matière. Vous quittez la réunion du cours pour travailler ensemble; l&#39;enseignant reste disponible dans la réunion du cours si vous avez une question.</li><li>Remise : le brouillon du rapport et le résumé, déposés dans l&#39;<strong>équipe Teams du cours</strong>. Travail <strong>formatif</strong>.</li></ul></div><hr><h2 id="contexte" tabindex="-1">Contexte <a class="header-anchor" href="#contexte" aria-label="Permalink to &quot;Contexte&quot;">​</a></h2><p>Vous avez les résultats de vos essais et un premier jet. Ce soir, vous l&#39;écrivez <strong>pour la personne qui va le lire</strong>. Mélanie ne connaît pas le vocabulaire du Web, elle a peu de temps, et elle doit pouvoir décider à partir de votre rapport.</p><blockquote><p><strong>Le test de ce soir :</strong> si Mélanie ne lit que le résumé, les titres, les tableaux et la première phrase de chaque section, comprend-elle l&#39;essentiel ?</p></blockquote><hr><h2 id="preparation" tabindex="-1">Préparation (5 min) <a class="header-anchor" href="#preparation" aria-label="Permalink to &quot;Préparation (5 min) {#preparation}&quot;">​</a></h2><ul class="checklist"><li><label><input type="checkbox"><span class="check-text">Ouvrir le rapport dans le dossier partagé de l&#39;équipe; si ce n&#39;est pas fait, <a href="./../fiches/eval1-gabarit-rapport.docx" download>télécharger le gabarit (Word)</a></span></label></li><li><label><input type="checkbox"><span class="check-text">Ouvrir aussi votre fiche du Lab 04 et les commentaires de l&#39;enseignant</span></label></li><li><label><input type="checkbox"><span class="check-text">Activer le <strong>suivi des modifications</strong> de Word (onglet Révision) : la relecture de la partie 3 se fera en commentaires</span></label></li><li><label><input type="checkbox"><span class="check-text">Répartir les parties 1 et 2 : qui écrit quoi. La personne qui relira une section à la partie 3 n&#39;est pas celle qui l&#39;a écrite.</span></label></li></ul><hr><h2 id="partie-1" tabindex="-1">Partie 1 — Votre question, pour Mélanie (30 min) <a class="header-anchor" href="#partie-1" aria-label="Permalink to &quot;Partie 1 — Votre question, pour Mélanie (30 min) {#partie-1}&quot;">​</a></h2><p>Dans la <strong>section 6.1</strong> (votre question, en profondeur), mettez au propre ce que vous avez tiré du Lab 04.</p><ul class="checklist"><li><label><input type="checkbox"><span class="check-text">Une <strong>phrase d&#39;ouverture</strong> qui donne déjà l&#39;essentiel (pas « dans cette section, nous présentons… »)</span></label></li><li><label><input type="checkbox"><span class="check-text">Le <strong>besoin</strong>, en rappel des sections 3 et 4, en quelques lignes</span></label></li><li><label><input type="checkbox"><span class="check-text">Les <strong>familles de solutions</strong>, y compris celles que vous n&#39;avez pas essayées</span></label></li><li><label><input type="checkbox"><span class="check-text">Le <strong>tableau de comparaison</strong> du gabarit, avec la ligne « Source(s) ou essai » remplie et les <strong>hypothèses</strong> du coût sur trois ans écrites sous le tableau</span></label></li><li><label><input type="checkbox"><span class="check-text">La sous-section <strong>« Avantages, limites et points à vérifier »</strong> : ce que le tableau veut dire pour l&#39;entreprise, outil par outil, <strong>pour ce client-ci</strong></span></label></li><li><label><input type="checkbox"><span class="check-text">Les <strong>résultats des essais</strong> résumés, chacun avec son renvoi : « (essai E2, annexe A) »</span></label></li><li><label><input type="checkbox"><span class="check-text">Les <strong>points qui restent à vérifier</strong> (vos « non vérifiables »)</span></label></li></ul><div class="bg-slate-50 border border-slate-200 text-slate-800 rounded-lg p-4 mb-5"><strong>La chasse au jargon</strong><br> Pendant que vous écrivez, notez dans un coin chaque terme technique que vous utilisez. Pour chacun, deux choix seulement, comme dans l&#39;<a href="./../modules/01-faisabilite/05-ecrire-pour-le-client#activite-1">activité 1</a> : <ul class="list-disc pl-5"><li><strong>l&#39;éviter</strong>, en disant ce qu&#39;il fait pour l&#39;entreprise;</li><li><strong>l&#39;expliquer la première fois</strong>, en quelques mots, s&#39;il revient souvent ou si Mélanie le reverra.</li></ul></div><hr><h2 id="partie-2" tabindex="-1">Partie 2 — La mise en contexte et la portée (10 min) <a class="header-anchor" href="#partie-2" aria-label="Permalink to &quot;Partie 2 — La mise en contexte et la portée (10 min) {#partie-2}&quot;">​</a></h2><p>Dans la <strong>section 2</strong> du rapport :</p><ul class="checklist"><li><label><input type="checkbox"><span class="check-text">Le client, son activité et sa situation actuelle : le site, les outils, la façon de prendre les réservations</span></label></li><li><label><input type="checkbox"><span class="check-text">Ce que le client demande, et pourquoi, avec des chiffres du mandat (document 3)</span></label></li><li><label><input type="checkbox"><span class="check-text">La <strong>portée</strong> : ce que ce rapport couvre, et ce qu&#39;il ne couvre pas encore (les choix, les coûts de construction et l&#39;échéancier viendront dans la proposition technique)</span></label></li></ul><div class="bg-yellow-50 border border-yellow-200 text-yellow-900 rounded-lg p-4 mb-5"><strong>Ne racontez pas le mandat à Mélanie</strong><br> Elle connaît son entreprise mieux que vous. La mise en contexte montre que <strong>vous</strong> avez compris : choisissez les faits qui comptent pour le projet, pas tous les faits. </div><hr><h2 id="partie-3" tabindex="-1">Partie 3 — Le test de Mélanie (20 min) <a class="header-anchor" href="#partie-3" aria-label="Permalink to &quot;Partie 3 — Le test de Mélanie (20 min) {#partie-3}&quot;">​</a></h2><p>Chaque membre relit une section <strong>qu&#39;il n&#39;a pas écrite</strong>, en se mettant dans la peau de Mélanie. Il ne corrige pas : il <strong>commente</strong> (onglet Révision, « Nouveau commentaire »).</p><table tabindex="0"><thead><tr><th style="text-align:left;">Ce qu&#39;on commente</th><th style="text-align:left;">Le commentaire</th></tr></thead><tbody><tr><td style="text-align:left;">Un terme que Mélanie ne comprendrait pas</td><td style="text-align:left;">« Jargon : à éviter ou à expliquer »</td></tr><tr><td style="text-align:left;">Une phrase qu&#39;il faut lire deux fois</td><td style="text-align:left;">« Trop long : couper en deux »</td></tr><tr><td style="text-align:left;">Une affirmation sans mesure ni source</td><td style="text-align:left;">« D&#39;où vient ce fait ? »</td></tr><tr><td style="text-align:left;">Des avantages et des limites qui répètent le tableau</td><td style="text-align:left;">« Qu&#39;est-ce que ça veut dire pour l&#39;entreprise ? »</td></tr><tr><td style="text-align:left;">Une recommandation, même déguisée</td><td style="text-align:left;">« Recommandation : garder le fait, retirer le choix »</td></tr></tbody></table><p>Pour finir, faites une recherche (<kbd>Ctrl</kbd>+<kbd>F</kbd>) dans tout le rapport : <code>recommand</code>, <code>il faudrait</code>, <code>devrait</code>, <code>meilleur</code>, <code>idéal</code>, <code>privilégier</code>. Chaque résultat se règle avant la remise.</p><p>L&#39;auteur de la section traite ensuite les commentaires. Ce qui n&#39;est pas réglé ce soir le sera à la maison.</p><hr><h2 id="partie-4" tabindex="-1">Partie 4 — Le résumé, première version (15 min) <a class="header-anchor" href="#partie-4" aria-label="Permalink to &quot;Partie 4 — Le résumé, première version (15 min) {#partie-4}&quot;">​</a></h2><p>Dans la <strong>section 1</strong>, en une demi-page au plus, en trois temps :</p><ol><li><strong>Ce que le projet demande</strong>, en deux ou trois phrases.</li><li><strong>Les trois ou quatre constats</strong> qui pèsent le plus sur la suite du projet, du plus bloquant au moins bloquant. Au moins un vient de vos essais; les autres peuvent venir des contraintes ou des risques.</li><li><strong>Ce qui suivra</strong> : la proposition technique, et les points à vérifier avec le client.</li></ol><ul class="checklist"><li><label><input type="checkbox"><span class="check-text">Il se lit sans le reste du rapport</span></label></li><li><label><input type="checkbox"><span class="check-text">Il ne décrit pas la table des matières</span></label></li><li><label><input type="checkbox"><span class="check-text">Aucun terme technique qui n&#39;est expliqué que plus loin</span></label></li><li><label><input type="checkbox"><span class="check-text">Aucune mesure de détail, aucun prix au mois : des coûts par année, en dollars canadiens</span></label></li><li><label><input type="checkbox"><span class="check-text">Aucune recommandation</span></label></li></ul><p>C&#39;est une <strong>première version</strong> : vous la reprendrez quand le rapport sera complet.</p><hr><h2 id="retour" tabindex="-1">Partie 5 — Préparer le retour (5 min) <a class="header-anchor" href="#retour" aria-label="Permalink to &quot;Partie 5 — Préparer le retour (5 min) {#retour}&quot;">​</a></h2><p>Au début de la <strong>séance 6</strong>, l&#39;enseignant lira quelques résumés <strong>sans nommer les équipes</strong>, et la classe dira ce qu&#39;elle en comprend. Copiez votre résumé dans un fichier à part, sans vos noms, pour le déposer avec le brouillon.</p><hr><h2 id="remise" tabindex="-1">Remise <a class="header-anchor" href="#remise" aria-label="Permalink to &quot;Remise&quot;">​</a></h2><ul class="checklist"><li><label><input type="checkbox"><span class="check-text">La section 6 de votre question est mise au propre : phrase d&#39;ouverture, tableau de comparaison avec ses hypothèses, avantages et limites, renvois à l&#39;annexe A</span></label></li><li><label><input type="checkbox"><span class="check-text">La section 2 contient la portée du rapport</span></label></li><li><label><input type="checkbox"><span class="check-text">Chaque section a été relue par un autre membre de l&#39;équipe; les commentaires sont réglés ou notés pour plus tard</span></label></li><li><label><input type="checkbox"><span class="check-text">Le brouillon est nommé <code>lab05-equipeN-brouillon.docx</code> et le résumé seul, sans vos noms, <code>lab05-equipeN-resume.docx</code></span></label></li><li><label><input type="checkbox"><span class="check-text">Les deux fichiers sont déposés dans l&#39;équipe Teams du cours</span></label></li></ul><hr><h2 id="et-ensuite" tabindex="-1">Et ensuite ? <a class="header-anchor" href="#et-ensuite" aria-label="Permalink to &quot;Et ensuite ?&quot;">​</a></h2><p>À la <strong>séance 6 (4 novembre)</strong>, on commence par la lecture de quelques résumés. Le reste de la soirée est un <strong>atelier de révision et de français</strong> : apportez un rapport <strong>complet</strong>, même imparfait. La remise de l&#39;évaluation 1 a lieu le <strong>11 novembre, avant 18 h 30</strong>.</p>',41)])])}const m=t(r,[["render",i]]);export{b as __pageData,m as default};
